const $=q=>document.querySelector(q);const esc=v=>displayNames(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sitePage='game',siteDetailId='';
let s=null;let tab='play',filter='all',recordType='year',statCategory='main';
let savedCareer=readAutosave(),saveMessage=savedCareer.error,newLifeApproved=false;
function autoSave(){if(!s)return;const result=writeAutosave(s);saveMessage=result.error;if(result.ok)savedCareer={exists:true,state:s,error:''};}
function requestNewLife(){newLifeApproved=false;if(s||savedCareer.exists){openDialog('<h2>新しい人生を始めますか？</h2><p>新しい選手を作成すると、現在のオートセーブを上書きします。</p><div class="dialog-actions">'+button('confirm-new','新しい人生へ','primary')+button('close','キャンセル','secondary')+'</div>');}else newPlayerDialog();}
const nav=[['play','◈','進行'],['stats','▤','成績'],['career','◇','キャリア']];
const button=(action,label,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function showError(msg){const host=$('#modal').open?$('#modal'):$('#app');const existing=host.querySelector('.action-error');if(existing)existing.remove();const message=document.createElement('p');message.className='action-error';message.setAttribute('role','alert');message.textContent=msg;host.prepend(message);}
const heading=(eyebrow,title,sub='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><span class="year-mark">${s.year}</span></div>`;
function abilityBars(all=false){const keys=s.player.role==='pitcher'?PITCH_KEYS:BAT_KEYS;return keys.map(k=>{const v=Math.round(s.player.abilities[k]);const grade=v>=85?'S':v>=70?'A':v>=55?'B':v>=40?'C':v>=25?'D':'E';return `<div class="ability"><span>${ABILITIES[k]}</span><div class="bar"><i style="width:${v}%"></i></div><b>${k==='velocity'?velocity(s):v}</b><span class="grade">${k==='velocity'?'km/h':grade}</span></div>`;}).join('');}
function statCards(st){const cells=s.player.role==='pitcher'?[['防御率',era(st).toFixed(2)],['勝利',st.wins],['奪三振',st.so],['投球回',innings(st)]]:[['打率',decimal(avg(st))],['本塁打',st.hr],['打点',st.rbi],['盗塁',st.sb]];return `<div class="stat-cards">${cells.map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>`;}
function journey(){const steps=[['elementary','小学生'],['middle','中学生'],['high','高校生'],['university','卒業後'],['pro','プロ'],['retired','引退']];const idx=s.retired?5:['university','overseas','corporate'].includes(s.stage)?3:isPro(s)?4:steps.findIndex(x=>x[0]===s.stage);return `<div class="journey">${steps.map(([id,label],i)=>`<div class="${i===idx?'active':i<idx?'done':''}"><span>${i<idx?'✓':String(i+1).padStart(2,'0')}</span>${label}</div>`).join('')}</div>`;}
function siteFrame(body,kind='page'){closeDialog();$('#app').innerHTML='<div class="site-screen site-'+kind+'"><main class="site-content">'+body+'</main></div>';}
function rememberSite(page,id=''){sitePage=page;siteDetailId=id;window.history?.pushState({diamondPage:page,id},'');}
function topPage(){document.title='白球人生 — 野球人生シミュレーション';siteFrame('<div class="site-home"><h1>白球人生</h1><div class="site-intro"><p>小学生から始まり、進学・ドラフト・プロ野球・海外挑戦、そして引退まで。ひとりの選手の野球人生を歩むシミュレーションゲームです。</p><p>選択肢を選びながら年月を進め、成績や能力、契約、タイトル、移籍など、自分だけのキャリアを作っていきます。</p></div><div class="site-start-actions">'+button('new','ニューゲーム','primary')+(savedCareer.state?button('resume','続きから','secondary'):'')+button('library-open','選手名鑑','secondary')+'</div>'+(saveMessage?'<p role="status">'+esc(saveMessage)+'</p>':'')+'</div><footer class="site-footer">'+gamePublicLinks()+'</footer>','top');}
function render(){if(sitePage==='library'){openCareerLibrary('',false);return;}if(sitePage==='detail'){viewSavedCareer(siteDetailId,false);return;}if(sitePage==='top'||!s){topPage();return;}document.title=`${s.player.name}｜白球人生`;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-tab="play"><span class="brand-icon">◇</span><span>DIAMOND<br><b>LIFE</b></span></a><div class="side-label">MY BASEBALL STORY</div><nav aria-label="メインメニュー">${nav.map(([id,icon,name])=>`<button data-action="nav" data-tab="${id}" class="nav-item ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span>${icon}</span>${name}</button>`).join('')}</nav><div class="side-player"><div class="jersey">${String(s.player.number).padStart(2,'0')}</div><strong>${esc(s.player.name)}</strong><span>${playerLabel(s)} / ${s.age}歳</span><small>${s.retired?'RETIRED':'YOUR STORY CONTINUES'}</small></div><div class="side-footer">白球人生 <span>v1.9</span></div></aside><div class="workspace"><header class="topbar"><span class="always-player"><b>${esc(s.player.name)}</b><span>背番号 ${s.player.number} / ${s.age}歳 / ${s.year}年${isPro(s)?4:[4,7,10][s.period]}月 / ${esc(s.team)}</span></span><div>${saveMessage?'<small role="status">'+esc(saveMessage)+'</small>':''}${button('new','ニューゲーム','small')}</div></header><main class="view-${tab}">${tab==='play'?play():tab==='abilities'?abilities():tab==='stats'?statsView():tab==='career'?career():tab==='team'?teamView():tab==='national'?nationalView():career()}</main><footer class="footnote">${esc(s.player.name)}の野球人生 <span>学校・球団・大会の進行は架空のゲーム設定です。</span></footer></div>`;}
function play(){
 if(s.retired)return afterlifeView()+button('final-career',finalCareerOpening===s?'最終キャリアへ移動中…':'最終キャリアを見る','primary',finalCareerOpening===s?'disabled':'')+button('share-result','結果をシェア','primary');
 const st=s.current.games?s.current:s.records.at(-1)?.stats||emptyStats();
 const recordYear=s.current.games?s.year:s.records.at(-1)?.year||s.year;
 const waiting=s.rosterDecision||s.injuryAdvice||s.postingReport||s.market&&!s.market.closed||s.notices.some(n=>!n.seen&&n.year===s.year)||s.nationalOffers?.length||s.participationReport||s.youthNotice||s.scoutPopup||s.pending||s.employment||s.contractOffers.length||s.retirementAdvice&&!s.retirementAdvice.answered;
 return `<section class="number-player"><div><h1><small class="jersey-inline">#${s.player.number}</small> ${esc(s.player.name)}</h1><p>${esc(s.team)} ・ ${playerLabel(s)} ／ ${handLabel(s)}</p>${rosterStatusView()}</div><strong>${s.age}<small>歳</small></strong></section>
 <div class="main-numbers"><section class="panel salary-summary"><span>今季の契約年俸</span><strong>${isPro(s)?money(s.salary):'—'}</strong><p>${s.activeContract&&isPro(s)?`${s.stage==='pro'?(s.contractStatus==='development'?'育成 ／ ':'支配下 ／ '):''}${s.activeContract.years}年契約 ／ ${s.activeContract.endYear}年まで`:'アマチュア選手'}</p></section><section class="panel number-year"><span>現在</span><strong>${s.year}<small>年</small></strong><p>${stageLabel(s)}</p></section></div>
 <section class="panel stats-panel"><div class="panel-title"><h2>${recordYear}年の成績${s.stage==='pro'?(s.records.at(-1)?.levels?' / 一軍':' / 旧記録'):''}</h2><span>${st.games}${s.player.role==='pitcher'?'登板':'試合'}${s.current.games?'':' / 確定分'}</span></div>${statCards(st)}<div class="stats-extra">${s.player.role==='pitcher'?`勝敗 ${st.wins}勝 ${st.losses}敗 ／ WHIP ${whip(st).toFixed(2)} ／ ${st.saves||0}S・${st.holds||0}H`:`安打 ${st.hits} ／ 出塁率 ${decimal(obp(st))} ／ 長打率 ${decimal(slg(st))} ／ OPS ${decimal(ops(st))}`}</div></section>
 ${s.records.at(-1)?.levels?button('level-summary',s.stage==='mlb'?'メジャー・マイナー比較':'一軍・二軍の成績を比較','secondary compact-level'):''}
 <section class="panel progression"><div class="advance-buttons">${!isPro(s)&&!waiting?button('advance',`${CONFIG.seasons[s.period]}だけ進める`,'secondary'):''}${waiting?button('next-popup','届いた話を確認する →','primary'):button('year',isPro(s)?'1シーズン進める →':'1年進める →','primary')}</div><div class="quick-links">${['pro','mlb'].includes(s.stage)?button('market-menu','契約・移籍','secondary'):''}${button('retire','引退を選ぶ','danger')}</div></section>
 ${recentNews()}`;
}
function salarySummary(){const previous=s.records.filter(r=>['pro','independent','mlb'].includes(r.stage)).at(-1)?.salary;return `<section class="panel salary-summary"><span>今季の年俸（1年分）</span><strong>${money(s.salary)}</strong><p>${previous===undefined?'初年度の契約':`前年 ${money(previous)} ／ ${salaryDifference(previous,s.salary)}`}</p>${s.activeContract?`<p >${s.activeContract.years}年契約・${s.activeContract.startYear}〜${s.activeContract.endYear}年<br>契約総額 ${money(s.activeContract.annual*s.activeContract.years)}</p>`:''}<small>生涯年俸 ${money(s.totalSalary)}（契約金を除く）</small></section>`;}
function abilities(){return `${heading('PLAYER','能力')}<section class="panel"><div class="panel-title"><h2>${s.player.role==='pitcher'?'投手能力':'野手能力'}</h2><b>総合 ${overall(s)}</b></div>${abilityBars()}</section>`;}
function table(rows,summary=true,category='main',highlight=false){if(!rows.length)return '<div class="empty"><span>◇</span><h3>これから刻まれる記録</h3><p>該当する成績はまだありません。プレイを進めると、ここに残ります。</p></div>';const pitcher=s.player.role==='pitcher',withSalary=rows.some(r=>Number.isFinite(r.salary)),withAllowance=rows.some(r=>r.stage==='pro'&&Number.isFinite(r.firstTeamAllowance));const fielding=category==='fielding';const labels=fielding?['試合','刺殺','補殺','失策','送球失策','併殺','守備率']:pitcher?['登板','勝','敗','防御率','投球回','奪三振','与四球','与死球','与四死球','失点','自責点','被安打','被本塁打','WHIP','S','H']:['試合','打率','打数','安打','本塁打','打点','盗塁','得点圏打率','四球','死球','三振','出塁率','長打率','OPS'];const detail=(st,v)=>st.detailsKnown?v:'—';const cells=st=>fielding?(st.fieldingKnown===true?[st.fieldGames,st.putouts,st.assists,st.errors,st.throwingErrors??'—',st.doublePlays,fieldingRate(st)===null?'—':decimal(fieldingRate(st))]:Array(7).fill('—')):pitcher?[st.games,st.wins,st.losses,era(st).toFixed(2),innings(st),st.so,st.allowedWalks,detail(st,st.allowedHbp),detail(st,st.allowedWalks+(st.allowedHbp||0)),detail(st,st.runsAllowed),st.er,st.allowedHits,detail(st,st.allowedHr),whip(st).toFixed(2),st.saves||0,st.holds||0]:[st.games,decimal(avg(st)),st.ab,st.hits,st.hr,st.rbi,st.sb,detail(st,st.rispAb?decimal(risp(st)):'—'),st.bb,st.hbp,detail(st,st.so),decimal(obp(st)),decimal(slg(st)),decimal(ops(st))];const highLabels=new Set(category==='fielding'?['試合','刺殺','補殺','併殺','守備率']:pitcher?['登板','勝','防御率','投球回','奪三振','WHIP','S','H']:['試合','打率','打数','安打','本塁打','打点','盗塁','得点圏打率','四球','出塁率','長打率','OPS']);
 const qualifies=(r,label)=>!r.partial&&(category==='fielding'?(label!=='守備率'||(r.stats.putouts||0)+(r.stats.assists||0)+(r.stats.errors||0)>=100):['防御率','WHIP'].includes(label)?r.stats.outs>=420:['打率','出塁率','長打率','OPS'].includes(label)?r.stats.ab>=440:label==='得点圏打率'?r.stats.rispAb>=100:true);
 const best=labels.map((label,i)=>{if(!highlight||!highLabels.has(label))return null;const values=rows.filter(r=>qualifies(r,label)).map(r=>cells(r.stats)[i]).filter(v=>v!=='—'&&Number.isFinite(Number(v))).map(Number);return values.length?(['防御率','WHIP'].includes(label)?Math.min(...values):Math.max(...values)):null;});
 const row=(r,total=false)=>`<tr class="${total?'total-row':''}"><th scope="row">${esc(r.label||r.year)}${!total&&r.age?`<small>${r.age}歳</small>`:''}</th><td>${esc(r.name||r.team||'—')}${r.stage?`<small>${STAGES[r.stage]}${r.pitchRole&&pitcher?' / '+PITCH_ROLES[r.pitchRole]:!pitcher&&r.batterRole?' / '+BATTER_ROLES[r.batterRole]:''}${r.result?' / '+esc(r.result):''}${r.teamResult?' / '+esc(teamResultLabel(r)):''}</small>`:''}</td>${withSalary?`<td class="salary-cell">${Number.isFinite(r.salary)?money(r.salary):'—'}</td>`:''}${withAllowance?`<td class="salary-cell">${Number.isFinite(r.firstTeamAllowance)?money(r.firstTeamAllowance):'—'}</td><td class="salary-cell">${Number.isFinite(r.salary)?money(r.paidSalary??r.salary):'—'}</td>`:''}${cells(r.stats).map((v,i)=>`<td${!total&&best[i]!==null&&qualifies(r,labels[i])&&v!=='—'&&Number(v)===best[i]&&(best[i]>0||['防御率','WHIP'].includes(labels[i]))?' class="career-best" title="表示中の年度別成績の最高記録（同記録を含む）"':''}>${v}</td>`).join('')}</tr>`;return `<div class="table-wrap"><table><thead><tr><th>年度 / 大会</th><th>所属 / 詳細</th>${withSalary?'<th>契約年俸</th>':''}${withAllowance?'<th>一軍追加報酬</th><th>年俸＋追加報酬</th>':''}${labels.map(l=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${summary?row({label:'通算',team:`${rows.length} 件の合計`,stats:sumStats(rows),salary:withSalary?rows.reduce((n,r)=>n+(r.salary||0),0):undefined,firstTeamAllowance:withAllowance?rows.reduce((n,r)=>n+(r.firstTeamAllowance||0),0):undefined,paidSalary:withSalary?rows.reduce((n,r)=>n+(r.paidSalary??r.salary??0),0):undefined},true):''}${rows.slice().sort((a,b)=>(a.year||0)-(b.year||0)).map(r=>row(r)).join('')}</tbody></table></div>`;}
function statsView(){if(recordType==='roster')return rosterHistoryView();const cupName={wbc:'世界野球選手権',olympics:'世界スポーツ大会'}[recordType];const cupHistory=cupName?s.nationalHistory.filter(r=>r.name===cupName):[];let rows=cupName?cupHistory.filter(r=>r.selected&&r.participated!==false&&r.stats).map(r=>({...r,label:r.year+' / '+(r.result||'結果未記録')})):recordType==='first'||recordType==='second'?levelRows(s.records,recordType):recordType==='pro'?s.records.filter(r=>['pro','independent','mlb'].includes(r.stage)):recordType==='minor'?s.records.filter(r=>r.stage==='mlb'&&r.levels?.second).map(r=>({...r,stats:r.levels.second})):recordType==='mlb'?s.records.filter(r=>r.stage==='mlb'):recordType==='year'?s.records:recordType==='koshien'?s.tournaments.filter(t=>t.koshien):s.tournaments;if(filter!=='all'&&!['pro','first','second','mlb','minor','wbc','olympics'].includes(recordType))rows=rows.filter(r=>r.stage===filter);return `${heading('THE RECORD BOOK','成績を振り返る','小さな一打も、大舞台の一球も。すべての数字を、ずっと。')}<section class="panel"><div class="filter-row"><div class="tabs">${[['year','年度別'],['pro','プロ通算・タイトル'],['first','国内プロ一軍'],['second','国内プロ二軍'],['mlb','メジャー成績'],['minor','マイナー成績'],['roster','登録・抹消'],['tournament','大会別'],['koshien','甲子園'],['wbc','世界野球選手権'],['olympics','世界スポーツ大会']].map(([id,label])=>`<button data-action="record-type" data-id="${id}" class="${recordType===id?'active':''}">${label}</button>`).join('')}</div><label ${['pro','first','second','mlb','minor','wbc','olympics'].includes(recordType)?'hidden':''}>時代 <select id="record-filter"><option value="all">すべて</option>${Object.entries(STAGES).map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="tabs stat-categories" aria-label="成績の種類">${[['main',s.player.role==='pitcher'?'投手成績':'打撃成績'],['fielding','守備成績']].map(([id,label])=>button('stat-category',label,statCategory===id?'active':'','data-id="'+id+'" aria-pressed="'+(statCategory===id)+'"')).join('')}</div>${statCategory==='fielding'?'<p class="micro">試合は守備に就いた試合数。併殺は守備で参加した併殺数です。送球失策は失策の内数。肩力は補殺・併殺、送球の正確さは送球失策に影響します。守備率＝（刺殺＋補殺）÷（刺殺＋補殺＋失策）。守備機会なし・未記録は「—」、未記録を含む通算も「—」です。</p>':''}<p class="micro">${cupName?'代表戦はシーズン・プロ通算成績と別集計です。辞退・選出なしは通算に含みません。':['first','second'].includes(recordType)?'国内プロのみ。一軍と二軍は別集計。年俸と一軍追加報酬は一・二軍共通です。二重に合算しません。更新前の区分不明な記録は含めません。':recordType==='pro'?'国内・海外プロ・独立リーグの合計。新記録は一軍・メジャーのみ。二軍・マイナー・代表戦を含みません。':recordType==='minor'?'海外マイナーの成績。メジャー・プロ通算には含みません。年俸は球団との共通契約額で、メジャー欄とは重複加算しません。':recordType==='mlb'?'海外メジャーの年度別・通算成績です。':recordType==='year'?'年度末に確定した成績。国内プロの新記録は一軍成績です。学生の年度成績には大会の成績を含みます。':'大会成績は年度成績の内数です。代表戦は別集計です。'} 通算率は合計の打数・投球回から算出します。追加前の詳細項目は「—」です。過去の数値は推測で埋めません。</p>${cupName?`<h2>${cupName}</h2><p>${rows.length}回出場 ／ ${rows.filter(r=>r.result==='優勝').length}回優勝</p>`:''}${['mlb','minor'].includes(recordType)?'<h2>'+(recordType==='mlb'?'メジャー':'マイナー')+'年度別・通算成績</h2>':''}<p class="micro">赤字は表示中の年度別成績の最高記録（同記録を含む）。率は規定相当の機会数を満たす年度で比較します。</p>${table(rows,true,statCategory,['year','pro','first','second','mlb','minor'].includes(recordType))}${cupName?`<details open><summary>代表選考・出場履歴</summary>${cupHistory.length?cupHistory.slice().sort((a,b)=>a.year-b.year).map(r=>`<p>${r.year}年${r.age?'（'+r.age+'歳）':''} ／ ${r.participated===false?'招集・辞退':r.selected?'出場・'+esc(r.result||'結果未記録'):'選出なし'}</p>`).join(''):'<p class="empty">開催年の選考結果はまだありません。</p>'}</details>`:''}${recordType==='pro'?`<details open><summary>獲得タイトル ${s.awards.length}件</summary>${s.awards.map(awardRow).join('')||'<p>獲得タイトルはまだありません。</p>'}</details>`:''}</section>${recordType==='year'&&s.current.games&&!s.records.some(r=>r.year===s.year)?`<section class="panel"><h2>${s.year}年 進行中の成績</h2>${table([{year:s.year,team:s.team,stats:s.current}],false,statCategory)}</section>`:''}`;}
function salaryChart(){if(!s.contracts.length)return '<p class="empty">プロ入り後、年俸の推移がここに残ります。</p>';const arr=s.contracts,max=Math.max(...arr.map(c=>c.salary),1);return `<div class="salary-chart" role="img" aria-label="年俸推移。下の契約履歴で金額を確認できます。">${arr.map(c=>`<div title="${c.year}年 ${money(c.salary)}"><i style="height:${Math.max(3,c.salary/max*110)}px"></i><span>${String(c.year).slice(2)}</span></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>年度</th><th>所属</th><th>年俸</th><th>来季契約</th><th>登録状況</th></tr></thead><tbody>${arr.slice().sort((a,b)=>a.year-b.year).map(c=>`<tr><td>${c.year}</td><td>${esc(c.team)}</td><td>${money(c.salary)}</td><td>${money(c.nextSalary)}</td><td>${esc(c.roster)}</td></tr>`).join('')}</tbody></table></div>`;}
function championshipView(){const rows=s.records.filter(r=>r.teamResult&&['pro','mlb'].includes(r.stage));if(!rows.length)return '';return `<section class="panel"><h2>チームの優勝歴</h2><p class="micro">所属球団の一軍実績です。二軍・育成所属時も球団の優勝として記録します。海外のリーグ優勝は上位3球団によるポストシーズンの勝者で、ワールドシリーズに進出します。</p>${[['pro','国内','日本一','japanChampion'],['mlb','海外','ワールドシリーズ優勝','worldChampion']].map(([stage,label,title,key])=>{const entries=rows.filter(r=>r.stage===stage);const winners=entries.filter(r=>r.teamResult.leagueChampion||r.teamResult[key]).sort((a,b)=>a.year-b.year);return `<h3 class="subheading">${label}</h3><p>リーグ優勝 ${entries.filter(r=>r.teamResult.leagueChampion).length}回 ／ ${title} ${entries.filter(r=>r.teamResult[key]).length}回</p>${winners.length?winners.map(r=>`<p>${r.year}年（${r.age??CONFIG.startAge+r.year-CONFIG.startYear}歳） ${esc(r.team)}：${r.teamResult.leagueChampion?'リーグ優勝':''}${r.teamResult[key]?' ／ '+title:''}</p>`).join(''):'<p class="micro">優勝の記録はまだありません。</p>'}`;}).join('')}</section>`;}
function career(){return `${heading('YOUR BASEBALL STORY',s.retired?'最後の一球、その先に。':'あなたの足跡',`${esc(s.player.name)} / ${s.year-CONFIG.startYear}年の歩み`)}<div class="career-metrics"><div><span>記録された年度</span><strong>${s.records.length}<small>年</small></strong></div><div><span>プロ実働</span><strong>${s.proYears}<small>年</small></strong></div><div><span>生涯年俸</span><strong class="money">${money(s.totalSalary)}</strong></div><div><span>代表出場</span><strong>${s.nationalHistory.filter(n=>n.selected&&n.participated!==false).length}<small>大会</small></strong></div></div><div class="two-columns"><details class="panel career-timeline"><summary>キャリア年表（${s.timeline.length}件）</summary><div class="full-timeline">${s.timeline.slice().sort((a,b)=>a.year-b.year).map(t=>`<div><b>${t.year}<small>${t.age??(CONFIG.startAge+t.year-CONFIG.startYear)}歳</small></b><p>${esc(t.text)}</p></div>`).join('')}</div></details><div>${championshipView()}${honorsView()}${allStarView()}</div></div><div class="career-histories"><section class="panel"><h2>ドラフト履歴</h2>${s.drafts.length?s.drafts.map(d=>`<div class="draft-entry"><b>${d.year}年 / ${d.type}${d.rank?' '+d.rank+'位':''}</b><p>${esc(d.team||'次の舞台で再挑戦')}</p><small>評価 ${d.score} / 100${d.rank?` ・ 年俸 ${money(d.salary)} ・ 契約金 ${money(d.bonus)}`:''}</small></div>`).join(''):'<p class="empty">高校3年の終了時に、最初のドラフトを迎えます。</p>'}</section>${injuryView()}</div>${s.retired?careerHigh():''}${s.retired&&!libraryViewing?'<div class="career-actions">'+button('share-result','結果をシェア','primary')+button('library-save','この選手を保存','primary')+button('library-open','選手名鑑','secondary')+'</div>':''}`;}
function teamHistory(){return `<div class="team-history">${s.teams.map(t=>`<div><b>${t.year}〜</b><span>${esc(t.team)}</span><small>${STAGES[t.stage]}${s.jerseyHistory?.find(j=>j.year===t.year&&j.team===t.team)?' / #'+s.jerseyHistory.find(j=>j.year===t.year&&j.team===t.team).number:''}</small></div>`).join('')}</div>`;}
function teamView(){return `${heading('CONTRACT','所属・契約',esc(s.team))}${isPro(s)?salarySummary():''}${clockView()}${roleControls()}${postingGoalView()}<section class="panel"><h2>これからの進路</h2><div class="quick-links">${!s.retired?button('market-menu','移籍を相談する','secondary')+button('retire','引退を選ぶ','danger'):''}${s.contractOffers.length?button('next-popup','契約提示を確認','primary'):''}</div><p>現役の上限は50歳。衰えや出場減少によって、戦力外やコーチ就任の打診があります。</p></section><section class="panel"><h2>所属履歴</h2>${teamHistory()}</section><details class="panel"><summary>年俸設定の参考資料</summary><p class="micro">実例を参考にした独自の査定です。実在選手の年俸を再現するものではありません。海外年俸は1ドル150円の固定換算を基準にしています。</p>${SALARY_SOURCES.map(x=>`<p><a href="${x.url}" target="_blank" rel="noopener">${x.label}</a></p>`).join('')}</details>`;}
function marketMenu(){openDialog(`<div class="dialog-head"><h2>移籍の相談</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div>${clockView()}<p>FAの交渉開始は権利の行使になります。宣言後に残留しても再取得が必要です。</p><div class="more-menu">${[['trade','トレード'],['fa','国内FA'],['overseasFa','海外FA'],['mlbFa','メジャーFA'],['posting','ポスティング']].map(([id,label])=>{const reason=eligibility(s,id);return `<div>${button('negotiate',label,'secondary wide',`data-id="${id}" ${reason?'disabled':''}`)}<p class="micro">${reason||'球団と交渉して条件を確認します。'}</p></div>`;}).join('')}</div>`);}
function showNextPopup(){render();if(s.retired)return;if(s.rosterDecision)return rosterDecisionDialog();if(s.injuryAdvice)return injuryAdviceDialog();if(s.participationReport)return participationReportDialog();if(s.nationalOffers?.length)return nationalOfferDialog();if(s.employment)return employmentDialog();if(s.postingReport)return postingResultDialog();if(s.market&&!s.market.closed&&s.market.year===s.year)return marketDialog();if(s.retirementAdvice&&!s.retirementAdvice.answered)return adviceDialog();if(s.youthNotice)return youthDialog();if(s.scoutPopup)return scoutDialog();if(s.pending)return choiceDialog();const notice=s.notices.find(n=>!n.seen&&n.year===s.year);if(notice)return noticeDialog(notice);if(s.contractOffers.length)return renewalDialog();}
function renewalDialog(){openDialog(`<div class="dialog-head"><h2>契約更改の提示</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div>${clockView()}<p>年俸は1年分の契約額です。国内支配下は420万円、育成は240万円が下限。国内支配下で1,600万円未満の場合は、一軍登録1日につき差額の150分の1を別途加算します（150日で満額）。複数年契約でも毎年の日数で加算します。</p><div class="path-options">${s.contractOffers.map(o=>`<div class="path-card"><h3>${o.development?'育成契約・リハビリ':s.stage==='pro'?(s.contractStatus==='development'?'育成契約':'支配下契約'):'選手契約'} ／ ${o.years}年</h3>${o.reason?'<p>'+esc(o.reason)+'</p>':''}<strong class="offer-salary">年俸 ${money(o.annual)}</strong><p>総額 ${money(o.annual*o.years)}<br>${o.year}〜${o.year+o.years-1}年</p>${incentiveText(o.incentive)}${button('sign-contract','この契約に合意','primary',`data-id="${o.id}"`)}</div>`).join('')}</div><div class="quick-links">${button('market-menu','移籍も検討する','secondary')}${button('retire','引退を選ぶ','danger')}</div>`);}
function employmentDialog(){const e=s.employment;openDialog(`<div class="dialog-head"><h2>${e.type==='released'?'戦力外通告':'引退後の仕事の打診'}</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div><p>${esc(e.from)}から${e.type==='released'?'来季の選手契約を結ばないと伝えられました。':'指導者・球団職員への転身を打診されました。現役続行も選べます。'}</p><div class="path-options">${e.options.map(o=>`<div class="path-card"><h3>${STAFF_ROLES[o.role]?STAFF_ROLES[o.role].label+'に就任':o.id==='stay'?'現役を続ける':esc(o.team)+'で続行'}</h3><p>${esc(o.team)}${o.attention?'<br><strong>★ '+esc(o.attention)+'</strong>':''}<br>${o.salary?'年俸 '+money(o.salary):'社会人野球・プロ年俸なし'}</p>${STAFF_ROLES[o.role]?'<p>選手として引退し、その後の人生を文章で振り返ります。</p>':''}${button('employment','この道を選ぶ','primary',`data-id="${o.id}"`)}</div>`).join('')}</div><div class="quick-links">${button('retire','現役引退を選ぶ','danger')}</div>`);}
function noticeDialog(n){openDialog(`<div class="dialog-head"><h2>${esc(n.title)}</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div><p>${esc(n.body)}</p><div class="dialog-actions">${button('notice-open','交渉してみる','primary',`data-id="${n.kind}"`)}${button('notice-skip','今回は見送る','secondary')}</div>`);}
function marketDialog(){const board=s.market;if(!board)return;openDialog(`<div class="dialog-head"><h2>交渉結果</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div><p>${esc(board.message)}</p>${board.closed?'<p>この交渉は終了しています。次のシーズンに再び交渉できます。</p>':`<div class="path-options">${board.offers.map(o=>`<div class="path-card"><h3>${esc(o.team)}</h3><strong class="offer-salary">年俸 ${money(o.salary)}</strong><p>${o.years||1}年契約 ／ 総額 ${money(o.salary*(o.years||1))}<br>${o.role} ／ ${o.stage==='mlb'?'海外プロ':'国内プロ'}</p>${offerTerms(o)}${button('offer','この条件で移籍する','primary',`data-id="${o.id}"`)}</div>`).join('')}</div>${button('remain',['fa','overseasFa'].includes(board.kind)?'FAを行使して残留する':'今の球団に残る','secondary wide')}`}`);}
function adviceDialog(){const a=s.retirementAdvice;if(!a||a.answered)return;openDialog(`<div class="dialog-head"><h2>球団からの引退勧告</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div><p>${esc(a.reason)}</p><p>現在の所属と年俸で現役続行できます。続けるか、区切りをつけるかはあなたが決めます。</p><div class="dialog-actions">${button('continue-career','現役を続ける','primary')}${button('retire','引退を考える','danger')}</div>`);}
function nationalTables(){return [...YOUTH_CUPS.map(c=>c.name),'世界野球選手権','世界スポーツ大会'].map(name=>{const rows=s.nationalHistory.filter(n=>n.selected&&n.participated!==false&&n.name===name).map(n=>({...n,label:`${n.year} / ${n.result}`,name}));return `<h3 class="subheading">${name} <span>${rows.length}回出場 / ${rows.filter(r=>r.result==='優勝').length}回優勝</span></h3>${table(rows)}`;}).join('');}
function nationalView(){const upcoming=[];for(let y=s.year;y<s.year+12;y++)for(const name of [...calendar(y),...YOUTH_CUPS.filter(c=>y>=c.start&&(y-c.start)%c.cycle===0).map(c=>c.name)])upcoming.push({year:y,name});return `${heading('BEYOND THE DIAMOND','日本代表','自分の一球が、国の一球になる。')}<section class="national-banner"><span>JAPAN NATIONAL TEAM</span><h2>世界の舞台へ。</h2><p>小・中・高校では年代別世界大会、プロでは世界野球選手権・世界スポーツ大会の代表を能力と成績で選考。<br>開催年だけに訪れる、特別なチャンス。</p><strong>${s.nationalHistory.filter(n=>n.selected).length}<small>代表大会</small></strong></section><div class="calendar-cards">${upcoming.slice(0,4).map(n=>`<div><span>${n.name}</span><strong>${n.year}</strong><small>ゲーム内開催予定</small></div>`).join('')}</div><p class="micro">U12・U15・U18世界大会は2年周期の架空大会。対象は小学10歳以上・中学生・高校生です。世界野球選手権は2026年から4年周期。世界スポーツ大会は2028年から4年周期、2032年は野球なしのゲーム設定。将来の実開催予定を示すものではありません。</p><section class="panel">${nationalTables()}</section><section class="panel"><h2>代表選考の履歴</h2>${s.nationalHistory.length?`<ul class="news">${s.nationalHistory.slice().reverse().map(n=>`<li><b>${n.year}</b>${n.name} / ${n.participated===false?'招集・辞退':n.selected?'選出・'+n.result:'選出なし'}</li>`).join('')}</ul>`:'<p class="empty">対象年代の開催年に選考結果が記録されます。</p>'}</section>`;}
function finalCareer(){return `<div class="retired-banner"><div class="eyebrow">THE LAST PITCH, A LIFETIME OF MEMORIES</div><h1>${esc(s.player.name)}、現役引退。</h1><p>${s.records[0]?.year||CONFIG.startYear} — ${s.year} / ${s.age}歳。すべての一球が、あなたの物語。</p></div>${afterlifeView()}${s.postCareer?`<section class="panel"><h2>引退後：${esc(s.postCareer.team)}の${esc(s.postCareer.role)}</h2><p>就任時年俸 ${money(s.postCareer.salary)}（選手の生涯年俸には含めません）</p></section>`:''}${career()}${careerHigh()}`;}
function openDialog(html){const d=$('#modal');if(d.open)d.close();d.innerHTML=html;d.showModal();}const closeDialog=()=>$('#modal').close();
function confirm(title,body,action){openDialog(`<div class="dialog-head"><h2>${title}</h2>${button('close','×','icon-button','aria-label="閉じる"')}</div><p>${body}</p><div class="dialog-actions">${button('close','キャンセル','secondary')}${button(action,'確定する','primary')}</div>`);}
function randomizePlayerForm(){const form=$('#new-player');if(!form)return;for(const name of ['role','throwHand','batHand','positionGroup','position','style','pitchStyle']){const field=form.elements.namedItem(name);field.selectedIndex=Math.floor(Math.random()*field.options.length);}$('#batter-options').hidden=form.elements.namedItem('role').value!=='batter';$('#pitcher-options').hidden=form.elements.namedItem('role').value!=='pitcher';$('#infield-options').hidden=form.elements.namedItem('positionGroup').value!=='infield';$('#outfield-note').hidden=form.elements.namedItem('positionGroup').value!=='outfield';}
function newPlayerDialog(){openDialog(`<div class="dialog-head"><div><div class="eyebrow">A NEW BEGINNING</div><h2>あなたの野球人生を始めよう。</h2></div>${button('close','×','icon-button','aria-label="閉じる"')}</div><p>6歳の春、はじめてのユニフォーム。</p><form id="new-player"><button type="button" data-action="random-player" class="secondary wide">ランダム</button><p class="micro">選手名以外のポジション・投打・守備位置・スタイルをまとめて設定します。ランダムを押すと、そのままゲームが始まります。</p><label>選手名<input name="name" maxlength="24" value="${esc(randomPlayerName())}" required autocomplete="off"></label><label>ポジション<select name="role"><option value="pitcher">投手</option><option value="batter">野手</option></select></label><div class="two-columns">${['throwHand','batHand'].map((key,i)=>`<label>${i?'打つ手':'投げる手'}<select name="${key}">${Object.entries(HANDS).map(([id,n])=>`<option value="${id}">${n}${i?'打ち':'投げ'}</option>`).join('')}</select></label>`).join('')}</div><div id="batter-options" hidden><label>守備区分<select name="positionGroup"><option value="infield">内野手</option><option value="outfield">外野手</option><option value="catcher">捕手</option></select></label><label id="infield-options">守備位置<select name="position">${['first','second','third','shortstop'].map(id=>`<option value="${id}">${POSITIONS[id]}</option>`).join('')}</select></label><p id="outfield-note" class="micro" hidden>外野の守備位置（左・中・右）はチームに任せます。</p><label>プレイスタイル<select name="style">${['balanced','average','power'].map(id=>`<option value="${id}">${STYLES[id].name}</option>`).join('')}<optgroup label="その他のスタイル"><option value="speed">韋駄天</option><option value="defense">守備職人</option></optgroup></select></label></div><label id="pitcher-options">投手スタイル<select name="pitchStyle">${Object.entries(PITCH_STYLES).map(([id,v])=>`<option value="${id}">${v.name}</option>`).join('')}</select></label><p class="micro">進行はこのブラウザに自動保存されます。保存された人生は開始画面の「続きから」で再開できます。</p><button type="submit" class="primary wide">グラウンドへ →</button></form>${button('library-open','マイ選手名鑑','secondary wide')}${gamePublicLinks()}`);}
function choiceDialog(){const p=s.pending;if(!p)return;const middle=p.type==='middle',high=p.type==='high';const draftInfo=p.type==='career'?`<div class="draft-result"><span>${p.draft.year} DRAFT</span><h3>${p.draft.type==='指名なし'?'今回は、指名なし。':`${p.draft.type==='育成'?'育成':''}ドラフト ${p.draft.rank}位指名`}</h3><p>${esc(p.draft.team||'野球人生は、まだ続く。次の道を選ぼう。')}</p><p>独立リーグ入団テスト：${p.draft.independentOffer?'合格・入団可能':'合格オファーなし'}</p><div>契約条件${p.draft.rank?` ・ 年俸 ${money(p.draft.salary)}<br>契約金 ${money(p.draft.bonus)}`:''}</div></div>`:'';let choices=middle?MIDDLE:high?SCHOOLS.filter(c=>c.active!==false).slice().sort((a,b)=>Number(s.schoolOffers.some(o=>o.id===b.id))-Number(s.schoolOffers.some(o=>o.id===a.id))):ROUTES.filter(r=>mayEnterUniversity(s)||!['university','overseas'].includes(r.id));if(p.type==='career'){choices=choices.filter(r=>r.id!==s.stage&&(r.id!=='independent'||p.draft.independentOffer));if(p.draft.type!=='指名なし')choices=[{id:'pro',name:p.draft.team,tag:'NPB相当のプロへ',desc:`提示条件で入団する。初年度年俸 ${money(p.draft.salary)}。`},...choices];if(p.draft.overseasOffer)choices=[{id:'mlb',name:p.draft.overseasOffer.team,tag:'海外ドラフト '+p.draft.overseasOffer.rank+'位',desc:'海外プロへ直接入団。年俸 '+money(p.draft.overseasOffer.salary)},...choices];if(['corporate','independent'].includes(s.stage))choices=[{id:'stay',name:s.team,tag:'現在の所属で続行',desc:'もう1年力を蓄え、次のドラフトへ。'},...choices];}openDialog(`<div class="dialog-head"><div><div class="eyebrow">CHOOSE YOUR PATH</div><h2>${middle?'中学での舞台を選ぶ':high?'高校、3年間の選択。':'次の夢を、選ぼう。'}</h2></div>${button('close','×','icon-button','aria-label="閉じる"')}</div>${draftInfo}<div class="path-options">${choices.map(c=>`<button data-action="choose" data-id="${c.id}" class="path-card ${high&&s.schoolOffers.some(o=>o.id===c.id)?'recruited':''}"><span class="tag">${high&&s.schoolOffers.some(o=>o.id===c.id)?'★ 推薦オファーあり ／ ':''}${c.tag}</span><h3>${esc(c.name)}</h3><p>${c.desc}</p>${high?schoolDetails(c):middle?middleDetails(c):''}<b class="path-arrow">この道へ →</b></button>`).join('')}</div><p class="micro">${high?'学校ごとに競争の厳しさや出場機会が異なります。':p.type==='career'?'大学進学は高校卒業時のみ選択可能。大学卒業後はプロ・社会人・独立リーグへ進みます。':'硬式クラブは試合数と注目度が高め。軟式は出場機会を得やすい環境です。'}</p>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{if(a==='site-top'){rememberSite('top');render();}else if(a==='site-game'){rememberSite('game');render();}else if(a==='library-open'){libraryCandidate=null;openCareerLibrary();}else if(a==='library-save'){if(!s?.retired)return;libraryCandidate=s;const result=saveRetiredCareer(s);if(result.ok)libraryCandidate=null;openCareerLibrary(result.ok?(result.alreadySaved?'この選手は保存済みです。':'選手を保存しました。'):result.error);}else if(a==='library-view'){viewSavedCareer(id);}else if(a==='library-delete'||a==='library-replace'){confirmLibraryChange(id,a==='library-replace');}else if(a==='library-confirm'){if(!libraryConfirmation||libraryConfirmation.id!==id)return;const result=libraryConfirmation.replace?saveRetiredCareer(libraryCandidate,{replaceId:id}):deleteSavedCareer(id);libraryConfirmation=null;if(result.ok)libraryCandidate=null;openCareerLibrary(result.ok?'名鑑を更新しました。':result.error);}else if(a==='library-back'){libraryConfirmation=null;openCareerLibrary();}else if(a==='final-career'){openFinalCareer();}else if(a==='share-result'){showCareerShare().catch(err=>showError(err.message));}else if(a==='share-send'){if(sharedCareer)shareCareerFile(sharedCareer).then(ok=>{if(!ok)$('#share-status').textContent='画像保存または文章コピーをご利用ください。';});}else if(a==='share-download'){if(sharedCareer){const url=URL.createObjectURL(sharedCareer.blob),link=document.createElement('a');link.href=url;link.download=sharedCareer.filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}}else if(a==='share-copy'){copyCareerShare();}else if(a==='resume'){const loaded=readAutosave();if(!loaded.state){savedCareer=loaded;saveMessage=loaded.error;render();return;}s=loaded.state;rememberSite('game');saveMessage='';tab='play';closeDialog();showNextPopup();}else if(a==='confirm-new'){newLifeApproved=true;newPlayerDialog();}else if(a==='roster-choice'){resolveRosterDecision(s,id);closeDialog();showNextPopup();}else if(a==='nav'){closeDialog();tab=b.dataset.tab;render();window.scrollTo(0,0);}else if(['career','stats','abilities','settings'].includes(a)){tab=a;render();window.scrollTo(0,0);}else if(a==='advance'||a==='year'){a==='year'?advanceYear(s):advance(s);render();showNextPopup();}else if(a==='national-accept'||a==='national-decline'){decideNational(s,a==='national-accept');closeDialog();render();showNextPopup();}else if(a==='participation-dismiss'){s.participationReport=null;closeDialog();render();showNextPopup();}else if(a==='news'){openDialog('<div class="dialog-head"><h2>最近の出来事</h2>'+button('close','×','icon-button')+'</div><ul class="news">'+s.news.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul>');}else if(a==='level-summary'){openDialog('<div class="dialog-head"><h2>所属区分ごとの成績</h2>'+button('close','×','icon-button')+'</div>'+farmSummary().replace('<details class="panel">','<details class="panel" open>'));}else if(a==='youth-dismiss'){s.youthNotice=null;closeDialog();render();showNextPopup();}else if(a==='scout-dismiss'){s.scoutPopup=false;closeDialog();render();showNextPopup();}else if(a==='pitch-wish'){requestPitchRole(s,id);render();}else if(a==='profile-save'){configurePlayer(s,$('#position-choice').value,$('#style-choice').value);render();}else if(a==='injury-continue'){continueAfterInjury(s);closeDialog();showNextPopup();}else if(a==='posting-alternative'){selectPostingAlternative(s,id);closeDialog();showNextPopup();}else if(a==='posting-dismiss'){s.postingReport=null;closeDialog();showNextPopup();}else if(a==='next-popup')showNextPopup();else if(a==='market-menu')marketMenu();else if(a==='sign-contract'){signRenewal(s,id);closeDialog();render();showNextPopup();}else if(a==='employment'){chooseEmployment(s,id);closeDialog();render();showNextPopup();}else if(a==='notice-open'){const n=s.notices.find(n=>!n.seen&&n.year===s.year);if(n)n.seen=true;const reason=eligibility(s,id);if(reason){closeDialog();showNextPopup();showError(reason);}else{negotiate(s,id);marketDialog();}}else if(a==='notice-skip'){const n=s.notices.find(n=>!n.seen&&n.year===s.year);if(n)n.seen=true;closeDialog();showNextPopup();}else if(a==='more'){openDialog('<div class="dialog-head"><h2>メニュー</h2>'+button('close','×','icon-button','aria-label="閉じる"')+'</div><div class="more-menu">'+nav.slice(3).map(([id,icon,label])=>button('nav',label,'secondary','data-tab="'+id+'"')).join('')+'</div>');}else if(a==='negotiate'){negotiate(s,id);marketDialog();}else if(a==='offer'){acceptOffer(s,id);s.postingReport=null;closeDialog();render();showNextPopup();}else if(a==='remain'){s.postingReport=null;remain(s);closeDialog();render();showNextPopup();}else if(a==='advice')adviceDialog();else if(a==='continue-career'){s.retirementAdvice.answered=true;s.timeline.push({year:s.year,text:'引退勧告を受け、現役続行を選択'});closeDialog();render();showNextPopup();}else if(a==='choice')choiceDialog();else if(a==='choose'){choose(s,id);closeDialog();render();}else if(a==='training'){s.training=id;render();}else if(a==='random-player'){randomizePlayerForm();startPlayerFromForm($('#new-player'));}else if(a==='new'||a==='edit')requestNewLife();else if(a==='close')closeDialog();else if(a==='stats-open'){tab='stats';recordType=id;filter='all';render();window.scrollTo(0,0);}else if(a==='record-type'){recordType=id;render();}else if(a==='stat-category'){if(['main','fielding'].includes(id))statCategory=id;render();}else if(a==='retire')retirementDialog();else if(a==='afterlife'){startAfterlife(s);render();}else if(a==='retire-confirm'||a==='retire-other'){retire(s,a==='retire-other'?'other':'auto');closeDialog();tab='play';render();window.scrollTo(0,0);}}catch(err){showError(err.message);}finally{if(s&&!a.startsWith('site-')&&!a.startsWith('library-')&&!['final-career','share-result','share-send','share-download','share-copy','resume','confirm-new','new','edit','close','nav','stats','career','abilities','settings','stats-open','record-type','stat-category','news','more','level-summary'].includes(a)){autoSave();if(saveMessage)render();}}});
document.addEventListener('change',e=>{if(e.target.name==='role'){const value=e.target.value;$('#batter-options').hidden=value!=='batter';$('#pitcher-options').hidden=value!=='pitcher';}if(e.target.name==='positionGroup'){$('#infield-options').hidden=e.target.value!=='infield';$('#outfield-note').hidden=e.target.value!=='outfield';}if(e.target.id==='record-filter'){filter=e.target.value;render();}});
function startPlayerFromForm(form){if((s||savedCareer.exists)&&!newLifeApproved){requestNewLife();return;}const f=new FormData(form);s=createPlayer(String(f.get('name')||''),String(f.get('role')));configureStart(s,Object.fromEntries(f.entries()));newLifeApproved=false;rememberSite('game');autoSave();closeDialog();tab='play';render();window.scrollTo(0,0);}
document.addEventListener('submit',e=>{if(e.target.id==='new-player'){e.preventDefault();startPlayerFromForm(e.target);}});
$('#modal').addEventListener('cancel',e=>{if(!s)e.preventDefault();});
render();
window.history?.replaceState({diamondPage:'top'},'');
window.addEventListener?.('popstate',event=>{const page=event.state?.diamondPage;sitePage=['top','game','library','detail'].includes(page)?page:'top';siteDetailId=event.state?.id||'';render();});

function schoolDetails(c){const x=schoolOutlook(s,c);return `<p><b>${x.recruited?'★ 推薦オファーあり：優先的な実戦機会':'一般入学'}</b><br>夏の甲子園出場見込み 約${x.chance}%<br>出場機会の目安 ${x.opportunity}%<br>全国大会での注目倍率 ${c.scout}倍</p><p class="micro">強豪校ほど全国で評価されやすい一方、控えになるリスクがあります。甲子園での活躍はドラフト評価を上げます。確率は現能力での目安です。</p>`;}
function scoutDialog(){openDialog(`<div class="dialog-head"><h2>高校スカウトからの推薦</h2></div><p>能力が評価され、高校から声がかかりました。中学卒業時の進路選択で推薦先を確認できます。</p>${s.schoolOffers.map(o=>`<p>${o.year}年：${esc(SCHOOLS.find(c=>c.id===o.id)?.name)}</p>`).join('')}${button('scout-dismiss','確認する','primary wide')}`);}
function roleControls(){if(s.retired)return '';if(s.player.role==='batter')return `<details class="panel"><summary>起用：${BATTER_ROLES[s.player.batterRole]||'控え'} ／ 守備位置・スタイル</summary><label>守備位置<select id="position-choice">${Object.entries(POSITIONS).filter(([id])=>id!=='dh').map(([id,n])=>`<option value="${id}" ${(s.player.naturalPosition||s.player.position)===id?'selected':''}>${n}</option>`).join('')}</select></label><label>スタイル<select id="style-choice">${Object.entries(STYLES).map(([id,v])=>`<option value="${id}" ${s.player.style===id?'selected':''}>${v.name}</option>`).join('')}</select></label><p>守備・走力に優れれば守備固め・代走要員、打撃に強みがあり守備や走力が落ちれば代打要員・代打の切り札として起用されます。打撃が伸びればレギュラーへ昇格できます。守備・盗塁の実績も年俸査定に反映します。得意分野が伸びやすくなり、それ以外の成長は控えめになります。変更は今後の成長・試合に反映します。DHはプロ・社会人でのみチーム判断により起用されます。</p>${button('profile-save','設定を反映','secondary')}</details>`;if(!canPitchRole(s))return '';return `<section class="panel"><h2>起用：${PITCH_ROLES[s.player.pitchRole]}</h2><p>希望：${PITCH_ROLES[s.player.roleWish]||'チームに任せる'}。次季の能力・チーム事情で決定します。先発はスタミナ45以上が目安です。</p><div class="quick-links">${Object.entries({auto:'おまかせ',...PITCH_ROLES}).map(([id,n])=>button('pitch-wish',n+'を希望','secondary',`data-id="${id}"`)).join('')}</div></section>`;}

function farmSummary(){const r=s.records.at(-1);if(!r?.levels||!['pro','mlb'].includes(s.stage))return '';const upper=r.stage==='mlb'?'メジャー':'一軍',lower=r.stage==='mlb'?'マイナー':'二軍';return `<details class="panel"><summary>${r.year}年の${upper}・${lower}比較</summary>${table([{...r,label:r.year+'年 '+upper,stats:r.levels.first},{...r,label:r.year+'年 '+lower,stats:r.levels.second}],false)}<p>${upper} ${r.levels.first.games}試合／登板 ・ ${lower} ${r.levels.second.games}試合／登板。通算と詳細は成績メニューへ。</p></details>`;}
function youthDialog(){const n=s.youthNotice;openDialog(`<div class="dialog-head"><h2>${esc(n.name)} 日本代表選出</h2></div><p>${n.year}年、世界の舞台に挑戦。大会結果は${esc(n.result)}でした。</p><p>個人成績と代表歴はキャリア内の日本代表の記録に保存しました。学校の成績とは別集計です。</p>${button('youth-dismiss','確認する','primary wide')}`);}

function middleDetails(c){return `<p class="micro">練習成長 ${c.growth.toFixed(2)}倍 ／ 季節の試合 ${c.games}試合<br>出場しやすさ ${c.opportunity>=1?'高':c.opportunity>=.8?'中':'低'} ／ 全国出場の基礎確率 ${Math.round(c.national*100)}%</p>`;}
function postingGoalView(){const c=s.postingChallenge;if(!c)return '';return `<section class="panel"><h2>ポスティングの条件</h2><p>${c.year}年・${esc(c.team)}：${c.label}<br>${c.status==='achieved'?'達成・球団承認を獲得':c.status==='failed'?'未達成':c.type==='years'?'許可まであと'+Math.max(0,c.eligibleYear-s.year+1)+'シーズン（'+c.eligibleYear+'年終了後）':'今季の条件に挑戦中'}</p><small>${postingApproved(s)?'現在の球団から承認済み。複数年契約中でも申請できます。':c.status==='achieved'?'承認は課題を出した球団でのみ有効です。':''}承認後も海外球団のオファーが必要です。</small>${!eligibility(s,'posting')?button('negotiate','ポスティングを申請する','primary',`data-id="posting"`):`<p class="micro">${esc(eligibility(s,'posting'))}</p>`}</section>`;}
function allStarView(){return `<details class="panel"><summary>オールスター・投票結果</summary><div class="table-wrap"><table><thead><tr><th>年度</th><th>年齢</th><th>所属</th><th>部門</th><th>投票数</th><th>順位</th><th>結果</th></tr></thead><tbody>${(s.allStars||[]).map(a=>`<tr><td>${a.year}</td><td>${a.age??s.records.find(r=>r.year===a.year)?.age??'—'}歳</td><td>${esc(a.team)}</td><td>${esc(a.position)}</td><td>${a.votes.toLocaleString()}票</td><td>${a.rank}位</td><td>${a.selected?'選出・'+a.method:'選外'}</td></tr>`).join('')}</tbody></table></div><p class="micro">架空の競合選手との部門内投票をシミュレーションしています。</p></details>`;}
function honorsView(){return s.honors?.filter(h=>h.title!=='野球殿堂入り').length?`<section class="panel honors"><h2>球史に刻まれた功績</h2>${s.recordHistory?.length?'<p class="micro">シーズン記録は国内一軍・海外メジャーのみ。世界記録は実在の主要リーグの歴史的記録を基準にしたゲーム内の設定です。</p>':''}${s.honors.filter(h=>h.title!=='野球殿堂入り').map(h=>`<p>🏆 ${esc(h.title)} ${h.value!==undefined?`${h.value}（従来 ${h.previous}） ／ ${h.year}年・${h.age}歳 ／ `:''}${esc(h.team)} ${h.title==='永久欠番'?'#'+h.number:''}</p>`).join('')}</section>`:'';}
function nationalOfferDialog(){const n=s.nationalOffers[0];openDialog(`<div class="dialog-head"><h2>${n.name} 日本代表への招集</h2></div><p>出場するか、今季の調整を優先するか選べます。</p><p>出場時：大会による欠場リスク13%、調整不足25%。海外選手との交流で成長する可能性55%、海外球団からの評価も上がります。</p><div class="dialog-actions">${button('national-accept','代表として出場する','primary')}${button('national-decline','辞退して調整を優先','secondary')}</div>`);}
function participationReportDialog(){const r=s.participationReport;openDialog(`<h2>${r.name}：${r.result}</h2><ul class="news">${r.effects.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>${button('participation-dismiss','シーズンに戻る','primary wide')}`);}

function clockView(){if(s.stage==='mlb')return '<div class="contract-clock"><b>メジャー登録換算 '+Math.floor(mlbService(s)/172)+'年'+mlbService(s)%172+'日</b><span>FAまで '+Math.max(0,1032-mlbService(s))+'日 ／ 残りオプション '+optionAllowance(s)+'年</span></div>';if(s.stage!=='pro')return '';const c=freeAgencyClock(s);return `<div class="contract-clock"><b>国内プロ実働 ${c.completed}年</b><span>国内FA：${faRemaining(c.rights.domesticDays)}</span><span>海外FA：${faRemaining(c.rights.overseasDays)}</span><span>一軍登録換算：${Math.floor(c.rights.credited/145)}年${c.rights.credited%145}日</span><span>ポスティング：${s.postingChallenge?.status==='pending'&&s.postingChallenge.team===s.team?s.postingChallenge.type==='years'?'球団許可まであと'+Math.max(0,s.postingChallenge.eligibleYear-s.year+1)+'シーズン':'球団の条件に挑戦中':c.posting?'あと'+c.posting+'年':eligibility(s,'posting')?'年数条件クリア':postingApproved(s)?'課題達成・申請可能':'申請可能'}</span><small>${!c.domestic?'国内復帰後の制度です。海外所属中は申請対象外。':c.contractLeft?'FAは契約満了まであと'+c.contractLeft+'年。ポスティングは契約期間中でも球団承認により申請可能。':'海外FAには球団承認不要。ポスティングには能力と球団承認も必要。'}</small><details><summary>FAの取得条件・日数の算定</summary><p>国内FAは原則8年、2007年以降の国内大学・社会人ドラフト入団は7年。海外FAは9年、行使後の再取得は4年。一軍登録145日を1年として、各年の上限は145日です。</p><p>新しいシーズンは日々の登録・抹消を記録して日数を集計します。過去の未記録シーズンのみ推定値です。二軍のみ・育成の期間は加算しません。前年に145日登録された選手の故障は最大60日を加算。投手の登板間隔など日付単位の特例は簡略化しています。</p><a href="${FA_RULES.source}" target="_blank" rel="noopener">NPB公式のFA規定</a></details></div>`;}
function offerTerms(o){const g=o.guarantees;if(!g)return incentiveText(o.incentive);return `${incentiveText(o.incentive)}<div class="offer-terms"><b>${g.label}</b><p>${g.regular?'✓ 契約期間中のレギュラー確約（故障時を除く）':'出場機会は実力・チーム事情で決定'}<br>${g.careerRole?'✓ 引退後の'+(g.careerRole==='manager'?'監督':'コーチ')+'就任保証':'引退後の役職保証なし'}</p>${g.careerRole?'<small>就任後の成績・在任期間は保証されません。</small>':''}</div>`;}
function awardRow(a){const r=s.records.find(r=>r.year===a.year&&r.team===a.team)||s.records.find(r=>r.year===a.year);const st=a.stats||r?.stats,age=a.age??r?.age;const detail=st?(s.player.role==='pitcher'?`防御率 ${era(st).toFixed(2)} ／ ${st.wins}勝 ／ ${innings(st)}回 ／ ${st.so}奪三振 ／ ${st.saves||0}S・${st.holds||0}H`:`打率 ${decimal(avg(st))} ／ ${st.hits}安打 ／ ${st.hr}本塁打 ／ ${st.rbi}打点 ／ ${st.sb}盗塁 ／ 守備貢献 ${(st.defenseRuns||0).toFixed(1)}`):'当時の詳細成績なし';return `<div class="award"><span>☆</span><div><strong>${esc(a.title)}</strong><small>${a.year}年 ／ ${age===undefined?'年齢不明':age+'歳'} ／ ${esc(a.team)}</small><p>${detail}</p></div></div>`;}
function recentNews(){const gains=s.news.filter(n=>/獲得|受賞|選出|優勝|承認|推薦|契約|オファー|天才|損傷|骨折/.test(n));const other=s.news.filter(n=>!gains.includes(n));const rows=[...gains,...other].slice(0,3);return `<section class="recent-news panel"><div class="panel-title"><h2>最近の出来事</h2>${button('news','すべて見る','secondary')}</div><ul>${rows.map(n=>`<li class="${gains.includes(n)?'news-gain':''}">${gains.includes(n)?'★ ':''}${esc(n)}</li>`).join('')}</ul></section>`;}
function afterlifeView(){if(!s.retired)return '';const a=s.afterlife;if(!a)return `<section class="panel"><h2>引退後の人生</h2><p>選手時代の記録を残したまま、その後の物語を作成します。物語はこのページを開いている間だけ閲覧できます。</p>${button('afterlife','引退後の物語を読む','primary')}</section>`;return `<section class="panel afterlife"><h2>引退後の人生：${a.route}</h2><p>${a.startAge}歳からの新しい道。優勝 ${a.titles}回 ／ 指導したプロ球団 ${a.teams.length}球団</p><p>${a.reputation}</p><details open><summary>成功も挫折も、その後の物語</summary><div class="afterlife-story">${a.entries.map(e=>`<article><b>${e.year}年・${e.age}歳</b><p>${esc(e.text)}</p></article>`).join('')}</div></details><small>結果はランダムなフィクションです。選手時代の年俸・成績とは別の物語として表示します。</small></section>`;}
function retirementDialog(){const p=careerPromise(s,s.careerPromises?.at(-1));openDialog(`<div class="dialog-head"><h2>現役を引退しますか？</h2>${button('close','×','icon-button')}</div><p>引退後は選手として進行できません。引退は取り消せません。引退後の成績・物語は、このページを開いている間だけ閲覧できます。</p>${p?`<p>契約時の保証：${esc(p.team)}の${p.role==='manager'?'監督':'コーチ'}に就任できます。</p>`:''}<div class="dialog-actions">${button('close','キャンセル','secondary')}${button('retire-confirm',p?'保証された指導者の道へ':'引退して次の人生へ','primary')}${p?button('retire-other','指導者契約を辞退して別の道へ','secondary'):''}</div>`);}

function incentiveText(i){return i?'<p class="offer-terms">出来高：毎年 '+esc(i.label)+'達成で '+money(i.amount)+'を追加（基本年俸とは別）</p>':'';}
function injuryView(){return '<details class="panel"><summary>故障歴 '+(s.injuries||[]).length+'件</summary>'+(s.injuries||[]).map(i=>'<p>'+i.year+'年・'+i.age+'歳 ／ '+esc(i.name)+' ／ 約'+i.totalDays+'日'+(i.decline?'・後遺症による能力低下':'')+'</p>').join('')+'</details>';}
function careerHigh(){const rows=s.records.filter(r=>['pro','mlb'].includes(r.stage)&&r.stats.games);if(!rows.length)return '<section class="panel"><h2>キャリアハイ</h2><p>国内・海外プロの一軍成績はありません。</p></section>';const pitch=s.player.role==='pitcher',keys=pitch?[['勝利','wins'],['奪三振','so'],['セーブ','saves'],['ホールド','holds']]:[['安打','hits'],['本塁打','hr'],['打点','rbi'],['盗塁','sb']];return '<section class="panel"><h2>キャリアハイ</h2>'+keys.map(([label,key])=>{const best=rows.reduce((a,b)=>(b.stats[key]||0)>(a.stats[key]||0)?b:a);return '<p><b>'+label+' '+(best.stats[key]||0)+'</b> ／ '+best.year+'年・'+best.age+'歳 ／ '+esc(best.team)+'</p>';}).join('')+(()=>{const qualified=rows.filter(r=>pitch?r.stats.outs>=420:r.stats.ab>=440);if(!qualified.length)return '<p>規定相当の打数・投球回に達した年度なし</p>';const best=qualified.reduce((a,b)=>(pitch?era(b.stats)<era(a.stats):avg(b.stats)>avg(a.stats))?b:a);return '<p><b>'+(pitch?'防御率 '+era(best.stats).toFixed(2):'打率 '+decimal(avg(best.stats)))+'</b> ／ '+best.year+'年・'+best.age+'歳 ／ '+esc(best.team)+'（規定相当）</p>';})()+'</section>';}

function injuryAdviceDialog(){
 openDialog('<div class="dialog-head"><h2>大けがと今後の現役生活</h2>'+button('close','×','icon-button')+'</div><p>'+esc(s.injuryAdvice.name)+'により能力が低下しています。療養して復帰を目指すか、引退するかを選んでください。</p><p>復帰まで残り約'+(s.health?.daysLeft||0)+'日。所属先・契約の打診がある場合は、この後に確認できます。</p><div class="dialog-actions">'+button('injury-continue','療養して現役を続ける','primary')+button('retire','引退について考える','secondary')+'</div>');
}
function postingResultDialog(){
 const report=s.postingReport,achieved=report.status==='achieved';
 const reason=eligibility(s,'posting');
 if(achieved&&!reason){
  negotiate(s,'posting',true);marketDialog();
  const content=$('#modal').innerHTML;openDialog('<h2>ポスティング条件：達成</h2><p>'+report.resultYear+'年 ／ '+esc(report.label)+'</p>'+content);
  return;
 }
 const applicable=s.stage==='pro'&&displayNames(report.team)===displayNames(s.team);
 openDialog('<div class="dialog-head"><h2>ポスティング条件：'+(achieved?'達成':'未達成')+'</h2>'+button('close','×','icon-button')+'</div><p>'+report.resultYear+'年 ／ '+esc(report.label)+'</p><p>'+(achieved?esc(reason):report.status==='pending'?'在籍期間の条件は継続中です。あと'+Math.max(0,report.eligibleYear-report.resultYear)+'シーズンです。':'今回は条件を達成できませんでした。次のシーズンの代案を選べます。')+'</p>'+(!achieved&&applicable?'<div class="path-options">'+button('posting-alternative','来季の個人成績で再挑戦','primary','data-id="stats"')+button('posting-alternative','あと1シーズン在籍して許可を得る','secondary','data-id="years"')+button('posting-alternative','現在の条件のまま残留する','secondary','data-id="stay"')+'</div>':button('posting-dismiss','確認して次へ','primary')));
}

function rosterStatusView(){
 if(!['pro','mlb'].includes(s.stage))return '';
 const history=s.rosterHistory?.findLast(r=>r.stage===s.stage&&r.days.at(-1)?.team===s.team);if(history)return '<p><strong>'+history.year+'年末：'+esc(ROSTER_LABELS[history.finalStatus])+'</strong> ／ 登録 '+history.counts.active+'日 ／ '+button('stats-open','登録・抹消を見る','text','data-id="roster"')+'</p>';
 const latest=s.records.at(-1),record=latest?.stage==='pro'&&displayNames(latest.team)===displayNames(s.team)?latest:null;
 const levels=s.currentLevels||record?.levels;
 const label=rosterFromGames(levels,s.contractStatus);
 return '<p class="roster-status"><strong>'+label+'</strong>'+(levels?' ／ '+(s.currentLevels?s.year:record.year)+'年：一軍 '+levels.first.games+'試合・二軍 '+levels.second.games+'試合':' ／ 出場実績はまだありません')+'</p>';
}

function rosterDecisionDialog(){
 const d=s.rosterDecision;
 if(d.type==='refusal'){openDialog('<h2>マイナー降格拒否後の進路</h2><p>球団と今後の処遇を協議します。トレード先：'+esc(d.tradeTeam)+'</p><div class="dialog-actions">'+button('roster-choice','メジャーで残留','primary','data-id="stay"')+button('roster-choice','トレードで移籍','secondary','data-id="trade"')+button('roster-choice','自由契約','danger','data-id="release"')+'</div>');return;}
 openDialog('<h2>'+ (d.type==='consent'?'マイナー配属への同意確認':'DFA・ウェーバー手続き')+'</h2><p>'+d.date+'の打診。'+(d.type==='dfa'?d.deadline+'までの7日以内に移籍またはマイナー配属を決定します。':'メジャー在籍5年以上のため、本人の同意が必要です。')+'</p>'+button('roster-choice','配属に同意する','primary','data-id="accept"')+(d.type==='consent'||d.mayElectFA?button('roster-choice',d.type==='consent'?'降格拒否権を行使する':'配属を拒否し自由契約を選ぶ','secondary','data-id="decline"'):'')+'<p>配属後も既存契約の年俸保証を維持します。</p>');
}
function rosterHistoryView(){
 const rows=(s.rosterHistory||[]).slice().reverse();
 return heading('ROSTER','日々の登録・抹消','登録日は休養日も集計。試合に出た日数とは別です。')+button('record-type','成績表に戻る','secondary','data-id="year"')+rows.map(r=>'<details class="panel"><summary>'+r.year+'年 ／ '+esc(r.days[0]?.team)+' ／ '+(r.stage==='mlb'?'メジャー':'一軍')+' '+r.counts.active+'日・ファーム '+r.counts.farm+'日</summary><p>FA算入 '+r.service+'日'+(r.stage==='mlb'?' ／ IL '+r.counts.il+'日 ／ オプション降格 '+r.demotions+'回':' ／ 故障特例 '+r.counts.injuryCredit+'日')+'</p><h3>公示履歴</h3>'+r.transactions.map(t=>'<p>'+t.date+' '+esc(ROSTER_LABELS[t.to]||t.to)+'：'+esc(t.reason)+(t.eligibleDate?' ／ 再登録可能日 '+t.eligibleDate:'')+'</p>').join('')+'<details><summary>日別の登録一覧（'+r.days.length+'日）</summary><div class="table-wrap"><table><thead><tr><th>日付</th><th>状態</th><th>試合出場</th><th>登録日数の対象</th></tr></thead><tbody>'+r.days.map(d=>'<tr><td>'+d.date+'</td><td>'+esc(ROSTER_LABELS[d.status])+'</td><td>'+(d.played?'出場':'—')+'</td><td>'+(d.service?'対象':'—')+'</td></tr>').join('')+'</tbody></table></div></details></details>').join('')+(rows.length?'':'<p>国内・海外プロのシーズンを進めると記録されます。</p>');
}

let sharedCareer=null;
async function showCareerShare(){
 if(!s?.retired)return;
 const player=s;
 openDialog('<div class="dialog-head"><h2>結果をシェア</h2>'+button('close','×','icon-button','aria-label="閉じる"')+'</div><p>キャリアカードを生成しています…</p>');
 const asset=await makeCareerCard(player);
 if(s!==player||!$('#modal').open)return;
 sharedCareer=asset;
 openDialog('<div class="dialog-head"><h2>結果をシェア</h2>'+button('close','×','icon-button','aria-label="閉じる"')+'</div><img style="display:block;width:100%;max-width:432px;height:auto;margin:0 auto" src="'+asset.preview+'" alt="引退後のキャリアカード"><div class="dialog-actions" style="flex-wrap:wrap">'+(canShareCareerFile(asset)?button('share-send','共有画面を開く','primary'):'')+button('share-download','画像保存','secondary')+button('share-copy','シェア文章をコピー','secondary')+'</div><p id="share-status" role="status">画像保存・文章コピーでもシェアできます。</p><label>シェア文章<textarea id="share-text" readonly style="display:block;box-sizing:border-box;width:100%;min-height:130px;margin-top:8px">'+esc(asset.text)+'</textarea></label>');
 if(canShareCareerFile(asset))await shareCareerFile(asset);
}
async function copyCareerShare(){
 if(!sharedCareer)return;
 try{await navigator.clipboard.writeText(sharedCareer.text);$('#share-status').textContent='シェア文章をコピーしました。';}
 catch{const field=$('#share-text');field.focus();field.select();$('#share-status').textContent='自動コピーに対応していません。選択された文章をコピーしてください。';}
}

let finalCareerOpening=null;
async function openFinalCareer(){
 if(!s?.retired||finalCareerOpening===s)return;
 const player=s;finalCareerOpening=player;render();
 try{await runFinalCareerAd(player,{persist:()=>{if(s===player)autoSave();}});}catch{}
 finally{if(finalCareerOpening===player)finalCareerOpening=null;if(s===player){closeDialog();tab='career';render();window.scrollTo(0,0);}}
}

let libraryCandidate=null,libraryConfirmation=null,libraryViewing=false;
function openCareerLibrary(message='',navigate=true){
 if(navigate)rememberSite('library');document.title='選手名鑑｜白球人生';
 const library=readCareerLibrary();
 siteFrame('<div class="dialog-head"><h1>選手名鑑</h1>'+button('site-top','トップへ戻る','secondary')+(s?button('site-game','ゲームへ戻る','secondary'):'')+'</div><p>保存選手 '+library.careers.length+' / '+savedCareerLimit()+'</p>'+(message?'<p role="status">'+esc(message)+'</p>':'')+(library.error?'<p role="alert">'+esc(library.error)+'</p>':'')+library.careers.map(entry=>{
 const p=entry.state,total=sumStats(p.records.filter(r=>['pro','mlb','independent'].includes(r.stage))),summary=p.player.role==='pitcher'?total.wins+'勝 ／ '+total.so+'奪三振 ／ '+total.saves+'セーブ':total.hits+'安打 ／ '+total.hr+'本塁打 ／ '+total.sb+'盗塁';return '<section class="panel"><h3>'+esc(p.player.name)+'</h3><p>'+esc(playerLabel(p))+' ／ '+p.age+'歳で引退 ／ '+p.proYears+'年のプロ生活 ／ 現役 '+p.records.length+'年</p><p>'+summary+'</p><p class="micro">'+esc((p.honors||[]).map(h=>h.title).concat((p.awards||[]).map(a=>a.title)).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).slice(0,3).join(' ／ ')||'栄誉の記録なし')+'</p><small>'+esc(entry.careerId)+'</small><div class="dialog-actions" style="flex-wrap:wrap">'+button('library-view','詳細を見る','primary','data-id="'+esc(entry.careerId)+'"')+button('library-delete','削除','danger','data-id="'+esc(entry.careerId)+'"')+(libraryCandidate&&libraryCandidate.careerId!==entry.careerId?button('library-replace','この選手と入れ替える','secondary','data-id="'+esc(entry.careerId)+'"'):'')+'</div></section>';
 }).join('')+(!library.careers.length&&!library.error?'<p>保存した引退選手はまだいません。</p>':''));
}
function confirmLibraryChange(id,replace){
 const entry=readCareerLibrary().careers.find(c=>c.careerId===id);if(!entry)return;
 if(replace&&!libraryCandidate?.retired)return;
 libraryConfirmation={id,replace};
 openDialog('<h2>'+ (replace?'選手を入れ替えますか？':'選手を削除しますか？')+'</h2><p>'+esc(entry.state.player.name)+'の保存記録を削除します。'+(replace?esc(libraryCandidate.player.name)+'を代わりに保存します。':'')+'この操作は取り消せません。</p><div class="dialog-actions">'+button('library-confirm',replace?'入れ替える':'削除する','danger','data-id="'+esc(id)+'"')+button('library-back','キャンセル','secondary')+'</div>');
}
function viewSavedCareer(id,navigate=true){
 const result=readCareerLibrary(),entry=result.careers.find(c=>c.careerId===id);if(!entry){openCareerLibrary(result.error||'選手が見つかりません。');return;}
 if(navigate)rememberSite('detail',id);
 const current=s;s=entry.state;libraryViewing=true;
 try{
  const section=(title,body)=>'<details class="panel"><summary>'+title+'</summary>'+body+'</details>';
  const pros=s.records.filter(r=>['pro','mlb','independent'].includes(r.stage));
  const national=s.nationalHistory.filter(r=>r.selected&&r.participated!==false&&r.stats);
  const minor=s.records.filter(r=>r.stage==='mlb'&&r.levels?.second).map(r=>({...r,stats:r.levels.second}));
  const records=[['全年度の成績',s.records],['プロ通算',pros],['国内一軍',levelRows(s.records,'first')],['国内二軍',levelRows(s.records,'second')],['海外メジャー',s.records.filter(r=>r.stage==='mlb')],['海外マイナー',minor],['代表成績',national],['大会成績',s.tournaments]];
  const body='<p>'+esc(playerLabel(s))+' ／ '+s.age+'歳で引退</p>'+((s.careerTypes||[]).length?'<p>'+s.careerTypes.map(esc).join(' ／ ')+'</p>':'')+career()+records.map(([title,rows])=>section(title,table(rows)+section('守備成績',table(rows,true,'fielding')))).join('')+section('獲得タイトル・表彰',s.awards.map(awardRow).join('')||'<p>記録なし</p>')+section('所属球団履歴',teamHistory())+section('背番号履歴',(s.jerseyHistory||[]).map(r=>'<p>'+r.year+'年 ／ '+esc(r.team)+' ／ #'+r.number+'</p>').join('')||'<p>記録なし</p>')+section('契約・最高年俸','<p>最高年俸 '+money(Math.max(0,...s.records.map(r=>r.salary||0)))+'</p>'+table(s.records.filter(r=>r.salary>0)))+(s.afterlife?section('引退後の人生',afterlifeView()):'');
  document.title=s.player.name+'の最終キャリア｜白球人生';
  siteFrame('<div class="dialog-head"><h1>'+esc(s.player.name)+'の最終キャリア</h1>'+button('library-back','選手名鑑に戻る','secondary')+'</div><p>'+esc(s.careerId)+'</p>'+body);
 }finally{s=current;libraryViewing=false;}
}
